/**
 * Microsoft Excel (SharePoint) Node - Version 1
 * Discriminator: resource=table, operation=lookup
 */


interface Credentials {
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Look for a specific column value and then return the matching row */
export type MicrosoftExcelSharePointV1TableLookupParams = {
  resource: 'table';
  operation: 'lookup';
  authentication?: 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * The SharePoint site the workbook lives in. Only needed when the workbook is chosen from the list or by ID.
 * @searchListMethod searchSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * The document library the workbook lives in. Only needed when the workbook is chosen from the list or by ID.
 * @searchListMethod searchLibraries
 * @default {"mode":"list","value":""}
 */
    library?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Pick the workbook by URL (no site or library needed), from the list, or by ID
 * @searchListMethod searchWorkbooks
 * @default {"mode":"url","value":""}
 */
    workbook?: { __rl: true; mode: 'url' | 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Sheet
 * @searchListMethod getSheets
 * @default {"mode":"list","value":""}
 */
    worksheet?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Table
 * @searchListMethod getTables
 * @default {"mode":"list","value":""}
 */
    table?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The name of the column in which to look for value
 */
    lookupColumn: string | Expression<string>;
/**
 * The value to look for in column
 */
    lookupValue: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Whether to return every matching row instead of only the first one
     * @default false
     */
    returnAllMatches?: boolean | Expression<boolean>;
  };
};

export type MicrosoftExcelSharePointV1TableLookupNode = {
  type: 'n8n-nodes-base.microsoftExcelSharePoint';
  version: 1;
  config: NodeConfig<MicrosoftExcelSharePointV1TableLookupParams> & { credentials?: Credentials };
};